/* H611: real a5xx 2D blit self-test. CP_SET_RENDER_MODE(BLIT2D) plus RB_2D_SRC/DST
 * plus CP_BLIT(COPY) moves bytes through the render backend, which CP_MEM_WRITE
 * never exercises. Register numbers are dword addresses taken from Mesa 25.2.8
 * src/freedreno/registers/adreno/a5xx.xml (RB_2D_SRC_INFO 0x2107, RB_2D_DST_INFO
 * 0x2110, GRAS_2D_SRC_INFO 0x2181, GRAS_2D_DST_INFO 0x2182) and the opcodes from
 * adreno_pm4.xml (CP_SET_RENDER_MODE 0x6c, CP_BLIT 0x2c). The a5xx blit needs no
 * shader. [0] submit rc, [1] wait rc, [2] fence, [3] run count, [4] matching
 * bytes, [5] first mismatching byte offset (0xffffffff when exact), [6] dst[0],
 * [7] src[0]. */
extern "C" { volatile uint32_t native_a540_blit_diag[8]; }
/* H612: real-size surface through the static GPU page table. [0] submit rc,
 * [1] wait rc, [2] fence, [3] run count, [4] matching pixels out of
 * kPatWidth*kPatHeight, [5] first failing destination pixel index
 * (0xffffffff when all match), [6] source allocation succeeded,
 * [7] destination allocation succeeded, [8] plane 0 row padding still clear
 * after the copy, [9] alpha plane still clear after the copy. H613 adds the
 * geometry detail: [10] row mask, bit y set when all kPatWidth pixels of
 * pattern row y matched, [11] the value actually found at the first failing
 * destination pixel, [12] how many pixels matched inside that first failing
 * row, which separates a whole missing row from a column-step error. */
extern "C" { volatile uint32_t native_a540_surface_diag[13]; }
